  "goal": [
    {
      "id": "end-to-end-data-flow",
      "insight": "Show the complete data pipeline from five distinct source categories through ingestion, Bronze/Silver/Gold medallion layers, to BI and ML consumption endpoints"
    },
    {
      "id": "governance-overlay",
      "insight": "Visually emphasize the cross-cutting data governance, access control, and lineage tracking mechanisms that span across all pipeline stages"
    },
    {
      "id": "volume-throughput",
      "insight": "Highlight the relative data volume flowing from each source category through the pipeline, making high-throughput paths visually prominent"
    },
    {
      "id": "transformation-stages",
      "insight": "Distinguish the three medallion layers (Bronze/Silver/Gold) by showing the nature and count of transformations applied at each stage"
    },
    {
      "id": "consumption-fanout",
      "insight": "Emphasize how Gold-layer datasets fan out to multiple consumption endpoints including dashboards, ML models, and API services"
    }
  ]
}
